def solve(grid):
    if not grid:
        return grid
    h = len(grid)
    w = len(grid[0])
    nz = []
    color = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                nz.append((r, c))
                color = grid[r][c]
    if not nz:
        return grid
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                out[r][c] = grid[r][c]
                continue
            d = min(max(abs(r - rr), abs(c - cc)) for rr, cc in nz)
            out[r][c] = color if d % 2 == 0 else 5
    return out
